local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local lookup = {}
for i = 1, #alphabet do
    lookup[alphabet:sub(i, i)] = i - 1
end

local decoded = {}
for i = 1, #encoded, 4 do
    local c1 = encoded:sub(i, i)
    local c2 = encoded:sub(i + 1, i + 1)
    local c3 = encoded:sub(i + 2, i + 2)
    local c4 = encoded:sub(i + 3, i + 3)

    local a = lookup[c1] or 0
    local b = lookup[c2] or 0
    local c = lookup[c3] or 0
    local d = lookup[c4] or 0

    local n = a * 262144 + b * 4096 + c * 64 + d
    decoded[#decoded + 1] = string.char(math.floor(n / 65536) % 256)

    if c3 ~= "=" then
        decoded[#decoded + 1] = string.char(math.floor(n / 256) % 256)
    end
    if c4 ~= "=" then
        decoded[#decoded + 1] = string.char(n % 256)
    end
end

local source = table.concat(decoded)
local fn, err = loadstring(source)
assert(fn, err)
return fn()
